import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Fishing & Money Guide","description":"","frontmatter":{},"headers":[],"relativePath":"info/fishing-money.md","filePath":"info/fishing-money.md"}'),i={name:"info/fishing-money.md"};function l(s,e,r,h,d,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="fishing-money-guide" tabindex="-1">Fishing &amp; Money Guide <a class="header-anchor" href="#fishing-money-guide" aria-label="Permalink to &quot;Fishing &amp; Money Guide&quot;">​</a></h1><p>How to catch magic enchantment books and make money on LlamaCraft.</p><hr><h2 id="catching-magic-books-while-fishing" tabindex="-1">Catching Magic Books While Fishing <a class="header-anchor" href="#catching-magic-books-while-fishing" aria-label="Permalink to &quot;Catching Magic Books While Fishing&quot;">​</a></h2><p>You don&#39;t need an enchanting table to get the best custom enchants. Grab a fishing rod and go fishing in any lake, river, or ocean!</p><p>While fishing, you have a chance to reel in a <strong>Sealed Tome</strong> (Magic Book). Right-click the book in your hand to open it and get a random custom enchant.</p><h3 id="the-3-book-types" tabindex="-1">The 3 Book Types <a class="header-anchor" href="#the-3-book-types" aria-label="Permalink to &quot;The 3 Book Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Book Tier</th><th style="text-align:left;">How Common Is It?</th><th style="text-align:left;">Examples of What You Can Get</th><th style="text-align:left;">Server Alert</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enchanted Tome (Common)</strong></td><td style="text-align:left;">About 1 in every 20 fish</td><td style="text-align:left;">Night Vision, Speed, Poison, Auto-Smelt</td><td style="text-align:left;">No</td></tr><tr><td style="text-align:left;"><strong>Arcane Tome (Rare)</strong></td><td style="text-align:left;">About 1 in every 40 fish</td><td style="text-align:left;">Lightning Strikes, Dodge Hits, Headshots, Arrow Harpoon</td><td style="text-align:left;">No</td></tr><tr><td style="text-align:left;"><strong>Relic Tome (Super Rare)</strong></td><td style="text-align:left;">About 1 in every 160 fish</td><td style="text-align:left;">Life Steal, 3x3 Mining, Exploding Arrows, Extra Hearts</td><td style="text-align:left;"><strong>Yes! Sends a celebration message to the whole server!</strong></td></tr></tbody></table><hr><h2 id="how-money-works" tabindex="-1">How Money Works <a class="header-anchor" href="#how-money-works" aria-label="Permalink to &quot;How Money Works&quot;">​</a></h2><ul><li><strong>Check Your Money</strong>: Type <code>/bal</code> in chat.</li><li><strong>Send Money to a Friend</strong>: Type <code>/pay &lt;player&gt; &lt;amount&gt;</code> (example: <code>/pay Steve 500</code>).</li><li><strong>Server Shop</strong>: Type <code>/shop</code> to buy building blocks or sell extra ores and crops.</li><li><strong>Auction House</strong>: Type <code>/ah</code> to look at cool enchanted weapons and armor other players are selling.</li><li><strong>Sell Your Own Item</strong>: Hold the item in your hand and type <code>/ah sell &lt;price&gt;</code> (example: <code>/ah sell 1000</code>).</li></ul>',11)])])}const m=t(i,[["render",l]]);export{y as __pageData,m as default};
